package atf.rentz.distribution.retirement;

import atf.rentz.distribution.publication.ReleasePublication;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.nio.file.Path;
import java.util.List;
import static atf.rentz.distribution.evidence.ReleaseEvidenceFiles.*;

/** Original qualification and Extents are read, never regenerated by retirement. */
public final class RetirementEvidence {
    private static final ObjectMapper JSON = new ObjectMapper().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION)
            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);
    public record Qualified(ReleaseRetirement.Plan plan, ReleasePublication.Plan downloads, String qualificationSha256) { }
    public static Qualified read(Path root, Path qualification, Path readme, Path downloads, Path components, Path nativeExtent) throws IOException {
        for (Path file : List.of(qualification, readme, components, nativeExtent)) externalRun(root, file.toAbsolutePath().getParent());
        externalRun(root, downloads);
        byte[] original = readExternalFile(qualification, 4 * 1024 * 1024);
        JsonNode rag = JSON.readTree(original), receipt = json(readme), retirement = receipt.path("retirement");
        String repository = rag.path("candidate").path("repository").asText();
        String version = rag.path("candidate").path("candidateVersion").asText();
        String source = rag.path("candidate").path("sourceCommit").asText();
        String digest = rag.path("releaseWorkflow").path("artifactSha256").asText();
        require(repository.matches("[A-Za-z0-9-]+/rentz") && source.matches("[a-f0-9]{40}")
                && version.matches("(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)")
                && digest.matches("[a-f0-9]{64}") && rag.path("releaseWorkflow").path("readyForMainPromotionReview").asBoolean(false)
                && rag.path("conflicts").isArray() && rag.path("conflicts").isEmpty(), "QUALIFICATION");
        for (String id : List.of("offline-regression", "component-extent-report", "android-jvm", "native-ui", "native-ui-report", "release-build", "local-catalog"))
            require(gate(rag, id).path("status").asText().equals("PASS"), "GATE");
        require(receipt.path("gate").asText().equals("readme-publication") && receipt.path("status").asText().equals("PASS")
                && receipt.path("channel").asText().equals("public") && receipt.path("version").asText().equals(version)
                && receipt.path("sourceCommit").asText().equals(source) && receipt.path("apkSha256").asText().equals(digest)
                && receipt.path("authenticatedDownload").asText().equals("PASS") && receipt.path("anonymousDownload").asText().equals("PASS")
                && retirement.path("allowed").asBoolean(false) && retirement.path("preserveSourceTags").asBoolean(false)
                && retirement.path("preserveAuditEvidence").asBoolean(false) && retirement.path("latestTag").asText().equals("v" + version)
                && retirement.path("qualificationSha256").asText().equals(sha256(original)), "README-PROOF");
        var proofs = retirement.path("extentEvidence");
        require(proofs.isArray() && proofs.size() == 2, "EXTENTS");
        for (int i = 0; i < 2; i++) {
            String id = i == 0 ? "component-extent-report" : "native-ui-report";
            Path file = i == 0 ? components : nativeExtent;
            JsonNode claim = gate(rag, id);
            byte[] bytes = readExternalFile(file, 128L * 1024 * 1024);
            require(source.equals(claim.path("artifactSourceCommit").asText()) && bytes.length == claim.path("artifactBytes").asLong(-1)
                    && sha256(bytes).equals(claim.path("receiptSha256").asText())
                    && file.getFileName().toString().equals(claim.path("receipt").asText()), "EXTENT-IDENTITY");
            int matches = 0;
            for (var proof : proofs) if (proof.path("gate").asText().equals(id)) {
                matches++;
                require(proof.path("status").asText().equals("PASS") && proof.path("sourceCommit").asText().equals(source)
                        && proof.path("sha256").asText().equals(sha256(bytes)) && proof.path("bytes").asLong(-1) == bytes.length, "EXTENT-PROOF");
            }
            require(matches == 1, "EXTENT-PROOF");
        }
        JsonNode github = json(downloads.resolve("github-release.json")), anonymous = json(downloads.resolve("public-download.json"));
        require(github.path("stage").asText().equals("PUBLISHED_AND_AUTHENTICATED_DOWNLOAD_VERIFIED")
                && github.path("repository").asText().equals(repository) && github.path("sourceCommit").asText().equals(source)
                && github.path("tag").asText().equals("v" + version) && github.path("latest").asText().equals("v" + version)
                && github.path("apkSha256").asText().equals(digest) && github.path("releaseId").isIntegralNumber()
                && github.path("releaseId").canConvertToLong() && github.path("releaseId").longValue() > 0
                && anonymous.path("stage").asText().equals("ANONYMOUS_DOWNLOAD_VERIFIED")
                && anonymous.path("authenticated").isBoolean() && !anonymous.path("authenticated").booleanValue()
                && anonymous.path("bothApkArchivesVerified").asBoolean(false), "DOWNLOAD-PROOF");
        String name = "RentzLab-" + version + ".apk";
        byte[] apk = readExternalFile(downloads.resolve("authenticated-" + name), 256L * 1024 * 1024);
        byte[] checksum = readExternalFile(downloads.resolve("authenticated-" + name + ".sha256"), 512);
        require(apk.length > 0 && sha256(apk).equals(digest)
                && new String(checksum, java.nio.charset.StandardCharsets.US_ASCII).strip().equals(digest + "  " + name), "PAYLOAD");
        for (String suffix : List.of(name, name + ".sha256")) {
            byte[] authenticated = readExternalFile(downloads.resolve("authenticated-" + suffix), 256L * 1024 * 1024);
            byte[] publicBytes = readExternalFile(downloads.resolve("anonymous-" + suffix), 256L * 1024 * 1024);
            require(java.util.Arrays.equals(authenticated, publicBytes), "DOWNLOAD-BYTES");
            verifyAsset(github.path("assets"), suffix, authenticated, false, repository, version);
            verifyAsset(anonymous.path("assets"), suffix, publicBytes, true, repository, version);
        }
        var plan = new ReleaseRetirement.Plan(repository, version, source, receipt.path("readmeCommit").asText(),
                github.path("releaseId").longValue(), receipt.path("directApkUrl").asText());
        return new Qualified(plan, new ReleasePublication.Plan(repository, repository, version, source,
                new ReleasePublication.Payload(name, downloads.resolve("authenticated-" + name), apk.length, digest),
                new ReleasePublication.Payload(name + ".sha256", downloads.resolve("authenticated-" + name + ".sha256"), checksum.length, sha256(checksum))), sha256(original));
    }
    private static void verifyAsset(JsonNode rows, String name, byte[] bytes, boolean anonymous, String repo, String version) throws IOException {
        String url = "https://github.com/" + repo + "/releases/download/v" + version + "/" + name;
        require(rows.isArray() && rows.size() == 2, "ASSETS"); int matches = 0;
        for (var row : rows) if (anonymous ? row.path("url").asText().equals(url) : row.path("name").asText().equals(name)) {
            matches++; require(row.path("http").asInt() == 200 && row.path("bytes").asLong(-1) == bytes.length
                    && row.path("sha256").asText().equals(sha256(bytes)), "ASSET");
        }
        require(matches == 1, "ASSETS");
    }
    private static JsonNode gate(JsonNode rag, String id) throws IOException {
        JsonNode found = null; require(rag.path("gates").isArray(), "GATES");
        for (var row : rag.path("gates")) if (row.path("id").asText().equals(id)) { require(found == null, "DUPLICATE-GATE"); found = row; }
        require(found != null, "MISSING-GATE"); return found;
    }
    private static JsonNode json(Path file) throws IOException { return JSON.readTree(readExternalFile(file, 4 * 1024 * 1024)); }
    private static void require(boolean value, String code) throws IOException { if (!value) throw new IOException("RETIREMENT-" + code); }
    private RetirementEvidence() { }
}
